/**
 * The purchase order of the W3C XML Schema Primer (Second Edition, W3C Recommendation 28 October 2004),
 * https://www.w3.org/TR/xmlschema-0/ section 2, "Basic Concepts: The Purchase Order": po.xsd and po.xml as printed,
 * under the W3C Document License (see UPSTREAM.md). Generated by a scratch script with JSON.stringify; the three edited
 * copies are string replacements of PO_XML, one mistake each:
 *   PO_MISSING_PARTNUM      '<item partNum="872-AA">' becomes '<item>'
 *   PO_QUANTITY_100         '<quantity>1</quantity>' (first item) becomes '<quantity>100</quantity>'
 *   PO_UNEXPECTED_ELEMENT   '<giftWrap>yes</giftWrap>' is added after the first item's USPrice
 * PO_XML_AS_PRINTED keeps the primer's own typo, '<!/comment>' for '</comment>', which is not well formed XML;
 * PO_XML is the same document with that typo corrected.
 */
export const PO_XSD = "<xsd:schema xmlns:xsd=\"http://www.w3.org/2001/XMLSchema\">\n\n  <xsd:annotation>\n    <xsd:documentation xml:lang=\"en\">\n     Purchase order schema for Example.com.\n     Copyright 2000 Example.com. All rights reserved.\n    </xsd:documentation>\n  </xsd:annotation>\n\n  <xsd:element name=\"purchaseOrder\" type=\"PurchaseOrderType\"/>\n\n  <xsd:element name=\"comment\" type=\"xsd:string\"/>\n\n  <xsd:complexType name=\"PurchaseOrderType\">\n    <xsd:sequence>\n      <xsd:element name=\"shipTo\" type=\"USAddress\"/>\n      <xsd:element name=\"billTo\" type=\"USAddress\"/>\n      <xsd:element ref=\"comment\" minOccurs=\"0\"/>\n      <xsd:element name=\"items\"  type=\"Items\"/>\n    </xsd:sequence>\n    <xsd:attribute name=\"orderDate\" type=\"xsd:date\"/>\n  </xsd:complexType>\n\n  <xsd:complexType name=\"USAddress\">\n    <xsd:sequence>\n      <xsd:element name=\"name\"   type=\"xsd:string\"/>\n      <xsd:element name=\"street\" type=\"xsd:string\"/>\n      <xsd:element name=\"city\"   type=\"xsd:string\"/>\n      <xsd:element name=\"state\"  type=\"xsd:string\"/>\n      <xsd:element name=\"zip\"    type=\"xsd:decimal\"/>\n    </xsd:sequence>\n    <xsd:attribute name=\"country\" type=\"xsd:NMTOKEN\"\n                   fixed=\"US\"/>\n  </xsd:complexType>\n\n  <xsd:complexType name=\"Items\">\n    <xsd:sequence>\n      <xsd:element name=\"item\" minOccurs=\"0\" maxOccurs=\"unbounded\">\n        <xsd:complexType>\n          <xsd:sequence>\n            <xsd:element name=\"productName\" type=\"xsd:string\"/>\n            <xsd:element name=\"quantity\">\n              <xsd:simpleType>\n                <xsd:restriction base=\"xsd:positiveInteger\">\n                  <xsd:maxExclusive value=\"100\"/>\n                </xsd:restriction>\n              </xsd:simpleType>\n            </xsd:element>\n            <xsd:element name=\"USPrice\"  type=\"xsd:decimal\"/>\n            <xsd:element ref=\"comment\"   minOccurs=\"0\"/>\n            <xsd:element name=\"shipDate\" type=\"xsd:date\" minOccurs=\"0\"/>\n          </xsd:sequence>\n          <xsd:attribute name=\"partNum\" type=\"SKU\" use=\"required\"/>\n        </xsd:complexType>\n      </xsd:element>\n    </xsd:sequence>\n  </xsd:complexType>\n\n  <!-- Stock Keeping Unit, a code for identifying products -->\n  <xsd:simpleType name=\"SKU\">\n    <xsd:restriction base=\"xsd:string\">\n      <xsd:pattern value=\"\\d{3}-[A-Z]{2}\"/>\n    </xsd:restriction>\n  </xsd:simpleType>\n\n</xsd:schema>\n";

